            <button class="nav-btn active" onclick="switchTab('estate', this)">领地概况</button>
            <button class="nav-btn" onclick="switchTab('roster', this)">英雄名册</button>
            <button class="nav-btn" onclick="switchTab('inventory', this)">行囊物资</button>
            <button class="nav-btn" onclick="switchTab('map', this)">探险地图</button>
            <button class="action-btn" onclick="render()" title="Refresh Data">↻</button>
            <button class="close-btn" onclick="toggleDash()">×</button>
        </div>

        <div class="dash-content">
            <!-- Tab: Estate -->
            <div id="tab-estate" class="panel active">
                <div class="grid-2">
                    <div style="grid-column: span 2;">
                        <div class="card-head" style="margin-bottom:5px;">继承人 (HEIR)</div>
                        <div id="heir-panel" class="heir-card-wrapper"></div>
                    </div>
                </div>
                <div class="grid-2" style="margin-top:20px;">
                    <div class="card">
                        <div class="card-head">世界状态</div>
                        <div class="row"><span>周数</span> <span class="t-red" style="font-size:1.4rem; font-family:var(--font-title);" id="est-week-big">0</span></div>
                        <div style="font-size:1.0rem; color:#777; margin-top:10px; background:#111; padding:10px; border:1px solid #222;" id="est-status">...</div>
                        <div style="margin-top:20px; border-top:1px dashed #333; padding-top:10px;">
                            <div class="row"><span>位置</span> <span id="est-loc" style="color:#eee">-</span></div>
                            <span class="t-mute" style="font-size:0.9rem;">当前使命:</span>
                            <div style="font-style:italic; color:#888; font-size:1.0rem; line-height:1.4; margin-top:4px;" id="est-mission">...</div>
                        </div>
                    </div>
                    <div class="card">
                        <div class="card-head">小镇设施 (Facilities)</div>
                        <div id="fac-list"></div>
                    </div>
                </div>
            </div>

            <!-- Tab: Roster -->
            <div id="tab-roster" class="panel">
                <div class="roster-stack" id="roster-list"></div>
            </div>

            <!-- Tab: Inventory -->
            <div id="tab-inventory" class="panel">
                <div class="grid-2">
                    <div class="card">
                        <div class="card-head">补给品</div>
                        <div class="inv-grid" id="inv-con"></div>
                    </div>
                    <div class="card">
                        <div class="card-head">礼物 & 珍藏</div>
                        <div class="inv-grid" id="inv-gifts"></div>
                    </div>
                </div>
            </div>

            <!-- Tab: Map -->
            <div id="tab-map" class="panel">
                <div class="card">
                    <div class="card-head">区域探索度</div>
                    <div id="map-list"></div>
                </div>
                <div class="card" style="margin-top:20px; border:1px solid #555;">
                    <div class="card-head" style="color:#eee;">当前探险</div>
                    <div class="row"><span>地点</span> <span class="t-gold" style="font-size:1.2rem;" id="exp-loc">-</span></div>
                    <div class="row"><span>目标</span> <span id="exp-goal">-</span></div>
                    <div style="margin-top:25px;">
                        <span class="t-mute" style="font-size:0.9rem; display:block; margin-bottom:8px;">出征队伍 (点击查看详情)</span>
                        <div class="exp-tabs-container">
                             <div class="exp-tab-group" id="exp-tab-group"></div>
                        </div>
                        <div class="exp-detail-view" id="exp-detail-view"></div>
                    </div>
                    <div id="exp-supplies-box" style="margin-top:15px; display:none; border-top:1px solid #333; padding-top:15px;">
                         <span class="t-mute" style="font-size:0.9rem; display:block; margin-bottom:8px;">携带物资</span>
                         <div class="inv-grid" id="exp-supplies"></div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

<script>
    const DICT = {
        fac: { 
            "stagecoach":"驿站马车", "blacksmith":"铁匠铺", "guild":"公会", "sanitarium":"疗养院", 
            "tavern":"酒馆", "abbey":"教堂", "mill":"磨坊", "bank":"银行", "cartographer":"制图师营地", 
            "puppet_theatre":"木偶剧场", "graveyard":"墓园", "survivalist":"生存训练营地", "nomad_wagon":"商人马车","granary":"果园","sanguine_vintners":"“猩红酿造”"
        },
        item: { "food":"食物", "torch":"火把", "blood":"血酿", "invitation":"邀请函", "flower":"花卉", "necklace":"项链", "ring":"戒指", "shovel":"铲子", "key":"钥匙", "bandage":"绷带", "herb":"药草", "holy_water":"圣水", "antivenom":"解毒剂" },
        reg: { "weald":"荒野", "warrens":"兽窟", "cove":"海湾", "ruins":"遗迹", "courtyard":"庭院", "farmstead":"农庄", "darkest_dungeon":"极暗地牢" },
        stat: { "atk":"攻击", "def":"防御", "hit":"命中", "crit":"暴击", "prec":"精准", "spd":"速度", "dodge":"闪避" }
    };

    const COND_MAP = {
        "中毒": { icon: "🦠", color: "#4caf50" },
        "流血": { icon: "🩸", color: "#f44336" },
        "燃烧": { icon: "🔥", color: "#ff5722" },
        "腐蚀": { icon: "☣️", color: "#cddc39" },
        "标记": { icon: "🎯", color: "#ff9800" },
        "眩晕": { icon: "💫", color: "#9e9e9e" },
        "恐怖": { icon: "💀", color: "#222" },
        "增益": { icon: "⬇️", color: "#cfaa6e" },
        "减益": { icon: "⬇️", color: "#f00" }
    };

    const MOCK = { world: { week:1 }, resource: { gold:0, shards:0 }, facility: {}, heir: { name:"?" }, roster: {}, inventory: {}, expedition: {} };
    let currentExpTab = 1;
    let expandedHeroes = new Set(); 

    async function getData() {
        try {
            if (typeof getLastMessageId !== 'function') return MOCK;
            const maxId = getLastMessageId();
            for(let i=0; i<15; i++){
                let cid = maxId - i;
                if(cid < 0) break;
                let msg = await getChatMessages(cid);
                if(Array.isArray(msg)) msg=msg[0];
                if(msg && msg.role === 'assistant'){ 
                    let v = null;
                    if(window.Mvu && Mvu.getMvuData) v = await Mvu.getMvuData({type:'message', message_id:msg.message_id});
                    else if(getVariables) v = await getVariables({type:'message', message_id:msg.message_id});
                    return (v && v.stat_data) ? v.stat_data : MOCK;
                }
            }
            return MOCK;
        } catch(e) { console.error(e); return MOCK; }
    }

    /* Mobile Interaction Handler */
    function mobileItemClick(el) {
        // Strict check: Only run on mobile/narrow screens
        if (window.innerWidth > 768) return; 

        const title = el.getAttribute('title');
        if (!title) return;

        const box = document.getElementById('mobile-tooltip-box');
        box.innerText = title;
        box.style.display = 'block';
    }

    function toggleHeroDetails(name) {
        if(expandedHeroes.has(name)) expandedHeroes.delete(name);
        else expandedHeroes.add(name);
        render(); 
    }

    function renderSkills(skills) {
        if (!skills) return '<div style="color:#555">无技能数据</div>';
        let html = '';
        if (Array.isArray(skills)) {
            skills.forEach(s => html += `<div class="skill-card"><div class="sk-head">${s}</div></div>`);
        } else {
            for(const [name, data] of Object.entries(skills)) {
                const tagClass = `sk-tag-${data.tag||'其他'}`;
                html += `
                <div class="skill-card ${tagClass}">
                    <div class="sk-head">${name} <span class="sk-type">${data.type||''} · ${data.tag||''}</span></div>
                    <div class="sk-val">${data.val||''}</div>
                </div>`;
            }
        }
        return html;
    }

    function renderTraits(traits) {
        if (!traits) return '<div style="color:#555">无特质</div>';
        let html = '';
        if (Array.isArray(traits)) {
            traits.forEach(t => html += `<div class="trait-item">${t}</div>`);
        } else {
            for(const [name, data] of Object.entries(traits)) {
                html += `<div class="trait-item">${name}<span class="trait-desc">${data.desc||''}</span></div>`;
            }
        }
        return html;
    }

    function createHeroStrip(name, h, mode='roster') {
        if (!h) return '';
        const isHeir = (mode === 'heir');
        const isExpanded = isHeir || (mode === 'expedition') || expandedHeroes.has(name);

        const hpP = (h.hp.current / h.hp.max) * 100;
        const strP = (h.stress / 200) * 100;
        const eq = h.equipment || {};

        let strColor = '#e0e0e0', barClass = "", strValClass = "val-str";
        if(h.stress >= 100) { strColor = '#af1e1e'; strValClass = "val-str high"; }
        if(h.stress >= 170) { strColor = '#000'; barClass = "stress-crit"; }

        let effectClass = "";
        const ms = h.mental_state || "正常";
        if (ms.includes("美德")) effectClass = "virtuous";
        else if (ms.includes("折磨") || ms.includes("Affliction")) effectClass = "afflicted";

        let eqHtml = '';
        if(eq.weapon) eqHtml += `<span title="武器" onclick="mobileItemClick(this)">⚔️ Lv.${eq.weapon}</span>`;
        if(eq.armor) eqHtml += `<span title="护甲" onclick="mobileItemClick(this)">🛡️ Lv.${eq.armor}</span>`;
        if(eq.trinkets) {
            if(Array.isArray(eq.trinkets)) {
                eq.trinkets.forEach(t => eqHtml += `<span class="trinket-badge" onclick="mobileItemClick(this)" title="${t}">💍${t}</span>`);
            } else {
                for(const [tName, tData] of Object.entries(eq.trinkets)) {
                    eqHtml += `<span class="trinket-badge" title="${tData.desc}" onclick="mobileItemClick(this)">💍${tName}</span>`;
                }
            }
        }

        let statHtml = '';
        const statOrder = ["atk", "spd", "hit", "crit", "def", "dodge", "prec"];
        const s = h.stats || {};
        statOrder.forEach(k => {
            statHtml += `<div class="hs-stat-item"><span class="hs-s-lbl">${DICT.stat[k]||k}</span><span class="hs-s-val">${s[k]!==undefined?s[k]:'-'}</span></div>`;
        });

        let condHtml = "";
        if(h.conditions) {
            h.conditions.forEach(c => {
                let meta = COND_MAP["减益"];
                for (const k in COND_MAP) { if (c.includes(k)) { meta = COND_MAP[k]; break; } }
                condHtml += `<span class="cond-badge" style="border-color:${meta.color}55"><span style="color:${meta.color}">${meta.icon}</span></span>`;
            });
        }

        let appHtml = '';
        const app = h.appearance || {};
        if(app.outfit) appHtml += `<div class="app-tag"><span class="app-lbl">服装:</span>${app.outfit}</div>`;
        if(app.features) appHtml += `<div class="app-tag"><span class="app-lbl">特征:</span>${app.features}</div>`; 
        if(app.body && !app.features) appHtml += `<div class="app-tag"><span class="app-lbl">身材:</span>${app.body}</div>`; 
        if(app.pose)   appHtml += `<div class="app-tag"><span class="app-lbl">姿势:</span>${app.pose}</div>`;

        let narHtml = '';
        const nar = h.narrative || {};
        if(nar.thought) narHtml += `<div class="nar-thought">" ${nar.thought} "</div>`;
        if(nar.action)  narHtml += `<div class="nar-action">⚡ ${nar.action}</div>`;

        const detailContent = `
            <div class="hs-extra">
                <div class="hs-appearance">
                    <div class="drawer-sec" style="width:100%">${appHtml || '<span style="color:#444">暂无外观描述</span>'}</div>
                    <div class="drawer-sec" style="width:100%">${narHtml || '<span style="color:#444">...</span>'}</div>
                </div>
                <div class="hs-narrative">
                    <div class="dt-grid">
                        <div><div class="dt-col-head">SKILLS</div>${renderSkills(h.skills)}</div>
                        <div><div class="dt-col-head">TRAITS</div>${renderTraits(h.traits)}</div>
                    </div>
                </div>
            </div>
        `;

        let stripHTML = `
        <div class="hero-strip ${effectClass} ${!isExpanded && mode === 'roster' ? 'expandable' : ''}" ${!isExpanded && mode === 'roster' ? `onclick="toggleHeroDetails('${name}')"` : ''}>
            <div class="hs-main" ${isExpanded && mode === 'roster' ? `onclick="toggleHeroDetails('${name}')"` : ''}>
                <div class="hs-sec hs-identity">
                    <div class="hs-name" title="${name}">${name}</div>
                    <div class="hs-class">Lv.${h.level} ${h.race||''} ${h.class}</div>
                    <div class="hs-equip">${eqHtml}</div>
                </div>
                <div class="hs-sec hs-bars">
                    <div class="hs-bar-row">
                        <span class="hs-bar-lbl">HP</span>
                        <div class="hs-bar-bg"><div class="hs-bar-fill f-hp" style="width:${hpP}%"></div></div>
                        <span class="hs-bar-val val-hp">${h.hp.current}/${h.hp.max}</span>
                    </div>
                    <div class="hs-bar-row">
                        <span class="hs-bar-lbl">STR</span>
                        <div class="hs-bar-bg"><div class="hs-bar-fill ${barClass}" style="width:${strP}%; background:${strColor};"></div></div>
                        <span class="hs-bar-val ${strValClass}">${h.stress}/200</span>
                    </div>
                </div>
                <div class="hs-sec hs-stats"><div class="hs-stat-grid">${statHtml}</div></div>
                <div class="hs-sec hs-meta">
                    ${!isHeir ? `<div style="font-size:0.85rem; color:#888;">${h.relationship||'陌生'} <span class="t-pink">♥${h.affection||0}</span></div>` : ''}
                    <div style="font-size:0.8rem; color:${effectClass==='virtuous'?'#cfaa6e':(effectClass==='afflicted'?'#a00':'#666')}">${ms}</div>
                    <div class="cond-row">${condHtml}</div>
                </div>
            </div>
            ${mode === 'roster' && !isExpanded ? `<div class="expand-btn">▼ EXPAND</div>` : ''}
            ${mode === 'roster' && isExpanded ? `<div class="expand-btn" onclick="toggleHeroDetails('${name}')">▲ COLLAPSE</div>` : ''}
            <div class="hs-drawer ${isExpanded ? 'always-open' : ''}">
                ${detailContent}
            </div>
        </div>`;
        return stripHTML;
    }

    function selectExpTab(idx) {
        currentExpTab = idx;
        const d = window._lastData; if(d) renderExpeditionDetail(d);
        document.querySelectorAll('.exp-tab-btn').forEach((btn, i) => {
            if (i+1 === idx) btn.classList.add('active'); else btn.classList.remove('active');
        });
    }

    function renderExpeditionTabs(d) {
        const team = d.expedition.team || {};
        const groupEl = document.getElementById('exp-tab-group');
        groupEl.innerHTML = '';
        for(let i=1; i<=4; i++) {
            let heroName = team['slot'+i];
            let inner = `<div class="tab-hero-name" style="color:#555">Empty</div>`;
            let animClass = "";
            let h = null;
            if(heroName && heroName !== '-') {
                if(d.heir && d.heir.name === heroName) h = d.heir;
                else if(d.roster && d.roster[heroName]) h = d.roster[heroName];
            }
            if(h) {
                const hpP = (h.hp.current / h.hp.max) * 100;
                const strP = (h.stress / 200) * 100;
                let strColor = '#fff';
                if(h.stress >= 100) strColor = '#af1e1e';
                if(h.stress >= 170) { strColor = '#000'; animClass += " stress-crit"; }
                const ms = h.mental_state || "";
                if (ms.includes("美德")) animClass += " virtuous";
                else if (ms.includes("折磨") || ms.includes("Affliction")) animClass += " afflicted";
                inner = `<div class="tab-hero-name">${heroName}</div>
                    <div class="tab-bars"><div class="tab-bar-bg"><div style="height:100%; width:${hpP}%; background:#8a0b0b;"></div></div>
                    <div class="tab-bar-bg"><div style="height:100%; width:${strP}%; background:${strColor};"></div></div></div>`;
            }
            const activeClass = (i === currentExpTab) ? 'active' : '';
            groupEl.innerHTML += `<div class="exp-tab-btn ${activeClass} ${animClass}" onclick="selectExpTab(${i})"><div style="font-size:0.75rem; color:#666; margin-bottom:2px;">POS ${i}</div>${inner}</div>`;
        }
    }

    function renderExpeditionDetail(d) {
        const detailEl = document.getElementById('exp-detail-view');
        const team = d.expedition.team || {};
        const heroName = team['slot'+currentExpTab];
        if (!heroName || heroName === '-') { detailEl.innerHTML = `<div class="empty-slot-msg">该位置暂无英雄数据</div>`; return; }
        let hero = null;
        let isHeir = false;
        if (d.heir && d.heir.name === heroName) { hero = d.heir; isHeir = true; }
        else if (d.roster && d.roster[heroName]) { hero = d.roster[heroName]; }
        if(hero) detailEl.innerHTML = createHeroStrip(heroName, hero, isHeir ? 'heir' : 'expedition');
        else detailEl.innerHTML = `<div class="empty-slot-msg">数据丢失 (${heroName})</div>`;
    }

    async function render() {
        const d = await getData();
        window._lastData = d; 
        document.getElementById('sb-week').innerText = d.world.week || 0;
        document.getElementById('sb-state').innerText = d.expedition.state || "Idle";
        document.getElementById('sb-gold').innerText = d.resource.gold || 0;
        document.getElementById('sb-shards').innerText = d.resource.shards || 0;

        const heirPanel = document.getElementById('heir-panel');
        if(d.heir) {
            if(!d.heir.hp) d.heir.hp = {current:10, max:10};
            if(!d.heir.stats) d.heir.stats = {};
            heirPanel.innerHTML = createHeroStrip(d.heir.name, d.heir, 'heir');
        }
        document.getElementById('est-loc').innerText = d.heir.location;
        document.getElementById('est-mission').innerText = d.heir.mission;
        document.getElementById('est-week-big').innerText = d.world.week;
        document.getElementById('est-status').innerText = d.world.status;

        const rList = document.getElementById('roster-list');
        rList.innerHTML = '';
        if(d.roster) {
            for(const [name, h] of Object.entries(d.roster)) {
                rList.innerHTML += createHeroStrip(name, h, 'roster');
            }
        }

        const fList = document.getElementById('fac-list');
        fList.innerHTML = '';
        if(d.facility) {
            for(const [k, v] of Object.entries(d.facility)) {
                let level = 0;
                let desc = "";
                let isBuilt = false;

                if (typeof v === 'object') {
                    level = v.level || 0;
                    desc = v.desc || "";
                } else if (typeof v === 'number') {
                    level = v;
                } else if (typeof v === 'string') {
                    if(v === 'built') level = 1;
                }

                isBuilt = (level > 0);
                let txt = isBuilt ? `Lv.${level}` : "未建";
                let col = isBuilt ? '#cfaa6e' : '#444';
                let name = DICT.fac[k] || k;

                fList.innerHTML += `
                <div class="fac-row" title="${desc}" onclick="mobileItemClick(this)" style="cursor:help">
                    <span class="fac-name">${name}</span>
                    <span class="fac-lvl" style="color:${col}">${txt}</span>
                </div>`;
            }
        }

        const renderGrid = (id, items, isTro) => {
            const el = document.getElementById(id);
            el.innerHTML = '';
            if(!items) return;
            for(const [k, v] of Object.entries(items)) {
                if(!isTro && v===0) continue;
                let name = isTro ? k : (DICT.item[k]||k);
                let count = isTro ? '★' : v;
                let title = isTro ? (v.desc || name) : name;

                el.innerHTML += `<div class="inv-slot" title="${title}" onclick="mobileItemClick(this)"><div>${name}</div><div class="inv-cnt">${count}</div></div>`;
            }
        };
        renderGrid('inv-con', d.inventory.consumables, false);

        const giftsEl = document.getElementById('inv-gifts');
        giftsEl.innerHTML = '';

        const GIFT_INFO = {
            "flower": "【花束】好感+1",
            "necklace": "【项链】好感+2",
            "ring": "【银戒】好感+3"
        };

        if(d.inventory.gifts) {
            for(const [k,v] of Object.entries(d.inventory.gifts)) {
                if(v>0) {
                    let tooltip = GIFT_INFO[k] || (DICT.item[k]||k);
                    giftsEl.innerHTML += `<div class="inv-slot" style="border-color:#7c6235" title="${tooltip}" onclick="mobileItemClick(this)"><div>${DICT.item[k]||k}</div><div class="inv-cnt">${v}</div></div>`;
                }
            }
        }
        if(d.inventory.trophies) {
             for(const [k,v] of Object.entries(d.inventory.trophies)) {
                let tooltip = "";
                if (v.desc) tooltip += v.desc;
                if (v.desc && v.effect) tooltip += "\n";
                if (v.effect) tooltip += "效果: " + v.effect;

                giftsEl.innerHTML += `<div class="inv-slot" style="color:#f00; border-color:#8a0b0b;" title="${tooltip}" onclick="mobileItemClick(this)"><div>${k}</div><div class="inv-cnt">★</div></div>`;
             }
        }

        const mList = document.getElementById('map-list');
        mList.innerHTML = '';
        if(d.world.exploration) {
            for(const [k, v] of Object.entries(d.world.exploration)) {
                let extra = "";
                if(k === 'farmstead' && d.expedition.farmstead_light) extra = ` <span class="t-cyan" style="font-size:0.7em">(${d.expedition.farmstead_light})</span>`;
                mList.innerHTML += `<div style="margin-bottom:8px;"><div class="row" style="margin:0;"><span class="t-mute">${DICT.reg[k]||k}${extra}</span> <span>${v}%</span></div><div class="bar-bg" style="height:4px;"><div class="bar-fill f-exp" style="width:${v}%"></div></div></div>`;
            }
        }
        document.getElementById('exp-loc').innerText = d.expedition.location || "Town";
        document.getElementById('exp-goal').innerText = d.expedition.goal || "None";

        renderExpeditionTabs(d);
        renderExpeditionDetail(d);

        const suppBox = document.getElementById('exp-supplies-box');
        const hasSupplies = d.expedition.supplies && Object.keys(d.expedition.supplies).length > 0;
        if (hasSupplies) {
            suppBox.style.display = 'block';
            renderGrid('exp-supplies', d.expedition.supplies, false);
        } else {
            suppBox.style.display = 'none';
        }
    }

    function toggleDash() {
        const vp = document.getElementById('dd-viewport');
        const d = document.getElementById('dashboard');
        vp.classList.toggle('expanded');
        d.classList.toggle('active');
        if(d.classList.contains('active')) render();
    }

    function switchTab(t, btn) {
        document.querySelectorAll('.panel').forEach(e => e.classList.remove('active'));
        document.getElementById('tab-'+t).classList.add('active');
        document.querySelectorAll('.nav-btn').forEach(e => e.classList.remove('active'));
        btn.classList.add('active');
    }

