<!-- SillyTavern 开场白切换核心脚本（修复跳转） -->
<script>
    (function() {
        // 确保全局函数存在，兼容SillyTavern环境
        window.switchToOpening = async function(cardElement, swipeId) {
            if (!cardElement) {
                console.error("[少女地牢] 无效的卡片元素");
                return;
            }

            // 防止重复点击造成多次切换
            if (cardElement.classList.contains('switching')) {
                console.warn("[少女地牢] 切换中，请稍后");
                return;
            }

            // 检查SillyTavern API 是否可用
            if (typeof window.getChatMessages !== 'function' || typeof window.setChatMessage !== 'function') {
                alert("错误：未检测到SillyTavern环境API (getChatMessages/setChatMessage)。\n请确保在酒馆插件/角色卡界面中查看此页面。");
                console.error("[少女地牢] SillyTavern API缺失");
                return;
            }

            // 添加切换样式，禁用点击
            cardElement.classList.add('switching');

            try {
                // 获取当前聊天消息（通常第一条为角色初始消息）
                const messages = await window.getChatMessages("0", { include_swipe: true });
                if (!messages || !Array.isArray(messages) || messages.length === 0) {
                    throw new Error("无法获取聊天消息，请确保当前存在对话记录。");
                }

                const firstMessage = messages[0];
                // 检查swipes数组是否存在并且包含对应索引的开场白
                if (!firstMessage.swipes || !firstMessage.swipes[swipeId]) {
                    throw new Error(`开场白索引 ${swipeId} 未找到。请确保角色卡中已配置对应的swipe内容 (范围0~${(firstMessage.swipes?.length || 0)-1})。`);
                }

                const targetSwipeContent = firstMessage.swipes[swipeId];
                // 调用setChatMessage切换当前消息的swipe，并刷新显示
                await window.setChatMessage(targetSwipeContent, 0, {
                    swipe_id: swipeId,
                    refresh: 'display_and_render_current'
                });
                // 可选：控制台输出成功
                console.log(`[少女地牢] 成功切换开场白, swipeId=${swipeId}`);
            } catch (err) {
                console.error("[少女地牢] 切换失败:", err);
                alert(`切换开场白失败: ${err.message || "未知错误"}\n请检查SillyTavern控制台获取详情。`);
                // 失败后恢复卡片样式，以便重新尝试
                cardElement.classList.remove('switching');
            } finally {
                // 确保延迟一点恢复样式（成功切换后页面聊天刷新，但卡片本身仍然可见，恢复点击）
                // 但需注意如果切换成功，当前HTML并未销毁，所以恢复样式可以让用户继续选择其他开局。
                setTimeout(() => {
                    if (cardElement) {
                        cardElement.classList.remove('switching');
                    }
                }, 500);
            }
        };
    })();
</script>
</body>
</html>
